    .string "module"
.L18090:
    .string "special-form"
.L18091:
    .string "(module name)"
.L18092:
    .string "Declare this file's module name."
.L18093:
    .string "export"
.L18094:
    .string "special-form"
.L18095:
    .string "(export name)"
.L18096:
    .string "Mark a name as part of the module's public surface."
.L18097:
    .string "pub"
.L18098:
    .string "special-form"
.L18099:
    .string "(pub defn name (params) body)"
